
import tkinter as tk
from tkinter import ttk, scrolledtext, messagebox
import threading
import concurrent.futures
import requests
from fake_headers import Headers
import time

class SMSBomberGUI:
    def __init__(self, root):
        self.root = root
        self.root.title("SMS Bomber - Android Version")
        self.root.geometry("800x700")
        self.root.resizable(False, False)
        
        # تنظیم تم تیره
        self.setup_dark_theme()
        
        # متغیرهای برنامه
        self.is_running = False
        self.attack_count = 0
        
        # ایجاد رابط کاربری
        self.create_widgets()
        
    def setup_dark_theme(self):
        """تنظیم تم تیره برای برنامه"""
        self.root.configure(bg='#2b2b2b')
        style = ttk.Style()
        style.theme_use('clam')
        
        # تنظیم رنگ‌ها
        style.configure('TLabel', background='#2b2b2b', foreground='white')
        style.configure('TButton', background='#3c3c3c', foreground='white')
        style.configure('TEntry', fieldbackground='#3c3c3c', foreground='white')
        style.configure('TFrame', background='#2b2b2b')
        style.configure('Header.TLabel', font=('Arial', 18, 'bold'), foreground='#F9F259')
        
    def create_widgets(self):
        """ایجاد ویجت‌های رابط کاربری"""
        
        # هدر برنامه
        header_frame = ttk.Frame(self.root)
        header_frame.pack(pady=20)
        
        title_label = ttk.Label(header_frame, text=" SMS Bomber ANDROID", style='Header.TLabel')
        title_label.pack()
        
        subtitle_label = ttk.Label(header_frame, text="_______________________________________________________________________________________________________________________________________________________________________________", foreground='#FFDF00')
        subtitle_label.pack()
        
        # بخش ورودی شماره
        input_frame = ttk.Frame(self.root)
        input_frame.pack(pady=20, padx=20, fill='x')
        
        ttk.Label(input_frame, text="number:").pack(anchor='w')
        
        self.phone_entry = ttk.Entry(input_frame, font=('Elham', 12), width=20)
        self.phone_entry.pack(pady=5, fill='x')
        self.phone_entry.insert(0, "09")
        
        # بخش تنظیمات
        settings_frame = ttk.Frame(self.root)
        settings_frame.pack(pady=10, padx=20, fill='x')
        
        ttk.Label(settings_frame, text="rounds:").grid(row=0, column=0, sticky='w', padx=5)
        self.count_spinbox = ttk.Spinbox(settings_frame, from_=1, to=100, width=10)
        self.count_spinbox.grid(row=0, column=1, padx=5)
        self.count_spinbox.set("1")
        
        ttk.Label(settings_frame, text="Thread:").grid(row=0, column=2, sticky='w', padx=20)
        self.thread_spinbox = ttk.Spinbox(settings_frame, from_=1, to=50, width=10)
        self.thread_spinbox.grid(row=0, column=3, padx=5)
        self.thread_spinbox.set("20")
        
        # دکمه‌های کنترل
        button_frame = ttk.Frame(self.root)
        button_frame.pack(pady=20)
        
        self.start_button = ttk.Button(button_frame, text=" start", command=self.start_attack, width=18)
        self.start_button.pack(side='left', padx=14)
        
        self.stop_button = ttk.Button(button_frame, text=" stop", command=self.stop_attack, width=15, state='disabled')
        self.stop_button.pack(side='left', padx=1)
        
        self.clear_button = ttk.Button(button_frame, text="delete log", command=self.clear_logs, width=15)
        self.clear_button.pack(side='left', padx=1)
        
        # بخش لاگ و نتایج
        log_frame = ttk.Frame(self.root)
        log_frame.pack(pady=10, padx=20, fill='both', expand=True)
        
        ttk.Label(log_frame, text="log:").pack(anchor='w')
        
        self.log_text = scrolledtext.ScrolledText(log_frame, height=15, bg='#45474B', fg='white', 
                                                  insertbackground='white', font=('Courier', 10))
        self.log_text.pack(fill='both', expand=True, pady=5)
        
        # وضعیت برنامه
        status_frame = ttk.Frame(self.root)
        status_frame.pack(pady=10, padx=20, fill='x')
        
        self.status_label = ttk.Label(status_frame, text="ready", foreground='#4CAF50')
        self.status_label.pack(side='left')
        
        self.stats_label = ttk.Label(status_frame, text="all:0 succes:0 unsucces:0", foreground='#FF9800')
        self.stats_label.pack(side='right')
        
